'use client'
import { useState, useRef } from "react";
import html2canvas from "html2canvas";

export default function Home() {
  const [text, setText] = useState("");
  const imageRef = useRef(null);

  // Download the image with the overlay text
  const handleDownload = async () => {
    if (imageRef.current) {
      const canvas = await html2canvas(imageRef.current);
      const dataUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = dataUrl;
      link.download = "image_with_text.png";
      link.click();
    }
  };

  return (
  <div className="flex items-center justify-center min-h-screen bg-gray-100">
    <div className="text-center">
      <h1 className="text-3xl font-bold mb-8">Overlay Text on Image</h1>
      
      <div className="mb-6">
        <input
          type="text"
          value={text}
          onChange={(e) => {setText(e.target.value)}}
          placeholder="Enter text"
          className="px-4 py-2 text-lg w-72 border border-gray-300 rounded-md"
        />
      </div>

      <div
        ref={imageRef}
        className="relative inline-block w-[500px] h-[500px] bg-cover bg-center text-black text-3xl flex items-center justify-center"
        style={{ backgroundImage: "url('/images/rxknephew.png')" }}
      >
        <span className="bg-white p-2 inline-block max-w-full">{text}</span>
      </div>

      <div className="mt-6">
        <button
          onClick={handleDownload}
          className="px-6 py-3 text-lg bg-blue-600 text-white rounded-md hover:bg-blue-700"
        >
          Download Image
        </button>
      </div>
    </div>
    </div>
  );
}
